//! Bit-compatibility with the TypeScript codecs, from `tests/vectors.json`
//! (generated by running the TS code, see the repository history).

use dz_encodings::base62::{self, Alphabet};
use dz_encodings::hangul;
use serde_json::Value;

fn vectors() -> Value {
    serde_json::from_str(include_str!("vectors.json")).unwrap()
}

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

fn s<'a>(v: &'a Value, k: &str) -> &'a str {
    v[k].as_str().unwrap()
}

fn alphabet(v: &Value) -> Alphabet {
    match s(v, "alphabet") {
        "mrfi" => Alphabet::Mrfi,
        "timestamp" => Alphabet::Timestamp,
        other => panic!("unknown alphabet {other}"),
    }
}

#[test]
fn hangul_bytes_encode_matches_ts() {
    let v = vectors();
    let cases = v["hangul_bytes"].as_array().unwrap();
    for c in cases {
        let bits = c["bits"].as_u64().unwrap() as u32;
        let bytes = unhex(s(c, "hex"));
        assert_eq!(
            hangul::encode_bytes_with_bits(&bytes, bits).unwrap(),
            s(c, "text"),
            "bits {bits} hex {}",
            s(c, "hex")
        );
        if bits == hangul::BITS {
            assert_eq!(hangul::encode_bytes(&bytes), s(c, "text"));
        }
        // TS decode of its own output (may carry one extra trailing zero byte).
        assert_eq!(
            hangul::decode_bytes_with_bits(s(c, "text"), bits).unwrap(),
            unhex(s(c, "decoded_hex"))
        );
    }
    assert!(cases.len() > 500);
}

#[test]
fn hangul_bytes_decode_matches_ts_including_errors() {
    for c in vectors()["hangul_bytes_decode"].as_array().unwrap() {
        let bits = c["bits"].as_u64().unwrap() as u32;
        let got = hangul::decode_bytes_with_bits(s(c, "text"), bits);
        match c["hex"].as_str() {
            Some(hex) => assert_eq!(got.unwrap(), unhex(hex), "text {:?}", s(c, "text")),
            None => assert!(got.is_err(), "text {:?} should fail", s(c, "text")),
        }
    }
}

#[test]
fn hangul_digits_match_ts() {
    for c in vectors()["hangul_digits"].as_array().unwrap() {
        let bits = c["bits"].as_u64().unwrap() as u32;
        let digits = c["digits"].as_u64().unwrap() as usize;
        let value: u128 = s(c, "value").parse().unwrap();
        let got = hangul::encode_digits_with_bits(value, digits, bits);
        match c["text"].as_str() {
            Some(text) => {
                assert_eq!(got.unwrap(), text);
                let back = hangul::decode_digits_with_bits(text, bits).unwrap();
                assert_eq!(back.to_string(), s(c, "decoded"));
            }
            None => assert!(got.is_err(), "{value} in {digits} digits should fail"),
        }
    }
}

#[test]
fn hangul_digits_decode_matches_ts_including_errors() {
    for c in vectors()["hangul_digits_decode"].as_array().unwrap() {
        let bits = c["bits"].as_u64().unwrap() as u32;
        let got = hangul::decode_digits_with_bits(s(c, "text"), bits);
        match c["value"].as_str() {
            Some(v) => assert_eq!(got.unwrap().to_string(), v),
            None => assert!(got.is_err(), "text {:?} should fail", s(c, "text")),
        }
    }
}

#[test]
fn base62_bytes_match_ts() {
    for c in vectors()["base62_bytes"].as_array().unwrap() {
        let bytes = unhex(s(c, "hex"));
        // Leading zero bytes are the intentional divergence, see
        // `base62_leading_zero_bytes_diverge_from_ts`.
        if bytes.first().is_none_or(|&b| b == 0) {
            continue;
        }
        let text = base62::encode_bytes(&bytes, Alphabet::Mrfi);
        assert_eq!(text, s(c, "text"), "hex {}", s(c, "hex"));
        assert_eq!(
            base62::decode_bytes(&text, Alphabet::Mrfi).unwrap(),
            unhex(s(c, "decoded_hex"))
        );
    }
}

#[test]
fn base62_bytes_decode_matches_ts_including_errors() {
    for c in vectors()["base62_bytes_decode"].as_array().unwrap() {
        // Texts starting with the zero digit (or empty) decode differently
        // on purpose, see `base62_leading_zero_bytes_diverge_from_ts`.
        if s(c, "text").is_empty() || s(c, "text").starts_with('0') {
            continue;
        }
        let got = base62::decode_bytes(s(c, "text"), Alphabet::Mrfi);
        match c["hex"].as_str() {
            Some(hex) => assert_eq!(got.unwrap(), unhex(hex), "text {:?}", s(c, "text")),
            None => assert!(got.is_err(), "text {:?} should fail", s(c, "text")),
        }
    }
}

/// Intentional divergence from the TS codec, which read the bytes as one big
/// number and lost leading zero bytes (`[0, 0, 1]` and `[1]` both gave "1";
/// empty and all-zero input gave "0"). Each leading zero byte is now one
/// leading '0' character. Inputs without leading zero bytes are unchanged.
#[test]
fn base62_leading_zero_bytes_diverge_from_ts() {
    let mut seen = 0;
    for c in vectors()["base62_bytes"].as_array().unwrap() {
        let bytes = unhex(s(c, "hex"));
        if bytes.first().is_some_and(|&b| b != 0) {
            continue;
        }
        seen += 1;
        let zeros = bytes.iter().take_while(|&&b| b == 0).count();
        let rest = &bytes[zeros..];
        let expected = format!(
            "{}{}",
            "0".repeat(zeros),
            if rest.is_empty() {
                String::new()
            } else {
                // The TS text of the remainder, from the TS vector itself
                // when it has no all-zero ambiguity.
                base62::encode_bytes(rest, Alphabet::Mrfi)
            }
        );
        assert_eq!(base62::encode_bytes(&bytes, Alphabet::Mrfi), expected);
        assert_eq!(
            base62::decode_bytes(&expected, Alphabet::Mrfi).unwrap(),
            bytes
        );
        if !rest.is_empty() {
            // TS text for the remainder equals the TS text of the whole
            // input (it dropped the zeros).
            assert_eq!(&expected[zeros..], s(c, "text"));
        }
    }
    assert!(seen > 20);
    // The TS "0" and "00" texts (empty / all-zero in TS) now mean one and two
    // zero bytes; "0001" is [0, 0, 0, 1].
    assert_eq!(base62::decode_bytes("0", Alphabet::Mrfi).unwrap(), vec![0]);
    assert_eq!(
        base62::decode_bytes("00", Alphabet::Mrfi).unwrap(),
        vec![0, 0]
    );
    assert_eq!(
        base62::decode_bytes("0001", Alphabet::Mrfi).unwrap(),
        vec![0, 0, 0, 1]
    );
    assert_eq!(
        base62::decode_bytes("", Alphabet::Mrfi).unwrap(),
        Vec::<u8>::new()
    );
    assert_eq!(base62::encode_bytes(&[], Alphabet::Mrfi), "");
}

#[test]
fn base62_unsigned_matches_ts() {
    for c in vectors()["base62_unsigned"].as_array().unwrap() {
        let alpha = alphabet(c);
        let width = c["width"].as_u64().unwrap() as usize;
        // The TS side uses bigint; values past u128 are not generated.
        let value: u128 = s(c, "value").parse().unwrap();
        let text = base62::encode_unsigned(value, width, alpha);
        assert_eq!(text, s(c, "text"));
        assert_eq!(
            base62::decode_unsigned(&text, alpha).unwrap().to_string(),
            s(c, "decoded")
        );
    }
}

#[test]
fn base62_unsigned_decode_matches_ts_including_errors() {
    for c in vectors()["base62_unsigned_decode"].as_array().unwrap() {
        let got = base62::decode_unsigned(s(c, "text"), alphabet(c));
        match c["value"].as_str() {
            // Beyond u128 the TS bigint keeps going; Rust reports Overflow.
            Some(v) => match v.parse::<u128>() {
                Ok(n) => assert_eq!(got.unwrap(), n),
                Err(_) => assert_eq!(got, Err(base62::Error::Overflow)),
            },
            None => assert!(got.is_err(), "text {:?} should fail", s(c, "text")),
        }
    }
}
